import Foundation
import Testing
@testable import WishboneCore

/// Runs `contract/conformance/compiled/*.json` (generated by `go run ./cmd/wbc conformance`)
/// against the harness rules in contract/README.md. Until that directory exists, every case
/// here is skipped (not failed) with a clear reason — the hand-written unit tests in the
/// other suites cover the same semantics with wire AST written by hand in the meantime.
private let compiledDir = repoRoot.appendingPathComponent("contract/conformance/compiled")

private func compiledDirectoryExists() -> Bool {
    var isDir: ObjCBool = false
    return FileManager.default.fileExists(atPath: compiledDir.path, isDirectory: &isDir) && isDir.boolValue
}

/// One vector from a compiled conformance file, kept as a raw `JSONValue` object plus its
/// `name`/`kind` for dispatch and display.
struct ConformanceCase: CustomStringConvertible, Sendable {
    let file: String
    let name: String
    let kind: String
    let fields: [String: JSONValue]

    var description: String { "\(file)/\(name)" }

    func field(_ key: String) -> JSONValue? { fields[key] }
}

/// `loadConformanceCases()`'s result, plus any per-file problems — surfaced as `Issue`s by
/// `compiledVectorsAreDiscovered()` rather than silently dropped.
struct ConformanceLoad: Sendable {
    let cases: [ConformanceCase]
    let failures: [String]
}

private func loadConformanceCases() -> ConformanceLoad {
    guard compiledDirectoryExists() else { return ConformanceLoad(cases: [], failures: []) }
    guard let files = try? FileManager.default.contentsOfDirectory(at: compiledDir, includingPropertiesForKeys: nil) else {
        return ConformanceLoad(cases: [], failures: ["could not list \(compiledDir.path)"])
    }
    var cases: [ConformanceCase] = []
    var failures: [String] = []
    for file in files.sorted(by: { $0.lastPathComponent < $1.lastPathComponent }) {
        guard file.pathExtension == "json", file.lastPathComponent != "errors.json" else { continue }
        do {
            let data = try Data(contentsOf: file)
            guard let arr = try JSONValue.parse(data).asArray else {
                failures.append("\(file.lastPathComponent): top level is not a JSON array")
                continue
            }
            for (i, entry) in arr.enumerated() {
                guard let obj = entry.asObject, let name = obj["name"]?.asString, let kind = obj["kind"]?.asString else {
                    failures.append("\(file.lastPathComponent)[\(i)]: missing 'name'/'kind'")
                    continue
                }
                cases.append(ConformanceCase(file: file.lastPathComponent, name: name, kind: kind, fields: obj))
            }
        } catch {
            failures.append("\(file.lastPathComponent): \(error)")
        }
    }
    return ConformanceLoad(cases: cases, failures: failures)
}

/// Harness rule 2: deep equality with 1e-9 tolerance on numbers (relative for |x| > 1).
private func approximatelyEqual(_ a: Value, _ b: Value, tolerance: Double) -> Bool {
    switch (a, b) {
    case let (.number(x), .number(y)):
        if x.isNaN, y.isNaN { return true }
        let scale = Swift.max(1, abs(y))
        return abs(x - y) <= tolerance * scale
    case let (.list(xs), .list(ys)):
        return xs.count == ys.count && zip(xs, ys).allSatisfy { approximatelyEqual($0, $1, tolerance: tolerance) }
    case let (.record(xs), .record(ys)):
        guard xs.count == ys.count else { return false }
        for (k, v) in xs { guard let other = ys[k], approximatelyEqual(v, other, tolerance: tolerance) else { return false } }
        return true
    default:
        return a == b
    }
}

@MainActor
@Suite struct ConformanceTests {
    // `nonisolated` — Swift Testing's `@Test(arguments:)` macro reads this for test discovery
    // outside of any actor context, before the (MainActor) test bodies ever run.
    nonisolated static let load = loadConformanceCases()
    nonisolated static var cases: [ConformanceCase] { load.cases }

    @Test(.disabled(if: !compiledDirectoryExists(), "contract/conformance/compiled/ does not exist yet — generated by `go run ./cmd/wbc conformance`"))
    func compiledVectorsAreDiscovered() {
        #expect(!Self.cases.isEmpty, "compiled/ exists but no vectors were found")
        for failure in Self.load.failures { Issue.record("conformance file failed to parse: \(failure)") }
    }

    @Test(
        "conformance",
        .disabled(if: !compiledDirectoryExists(), "contract/conformance/compiled/ does not exist yet"),
        arguments: Self.cases
    )
    func runVector(_ vector: ConformanceCase) async throws {
        switch vector.kind {
        case "expr": try runExprVector(vector)
        case "handler", "event": try await runHandlerOrEventVector(vector)
        case "timeline": try runTimelineVector(vector)
        default: Issue.record("unknown vector kind '\(vector.kind)' in \(vector)")
        }
    }

    // MARK: expr

    private func runExprVector(_ vector: ConformanceCase) throws {
        guard let docWire = vector.field("document") else { Issue.record("\(vector): missing document"); return }
        let document = try Document(wire: docWire)
        let interpreter = Interpreter(document: document)
        guard let exprWire = vector.field("expr") else { Issue.record("\(vector): missing expr"); return }
        let expr = try Expr(wire: exprWire)
        let scope = try makeScope(vector, document: document, interpreter: interpreter)
        let result = try interpreter.eval(expr, scope: scope)
        let expected = Value(wire: vector.field("expect") ?? .null)
        #expect(approximatelyEqual(result, expected, tolerance: 1e-9), "\(vector): got \(result), expected \(expected)")
    }

    // MARK: handler / event

    private func runHandlerOrEventVector(_ vector: ConformanceCase) async throws {
        guard let docWire = vector.field("document") else { Issue.record("\(vector): missing document"); return }
        let document = try Document(wire: docWire)
        let interpreter = Interpreter(document: document)
        let scope = try makeScope(vector, document: document, interpreter: interpreter)
        let sink = RecordingEffectSink()
        if let callsObj = vector.field("calls")?.asObject {
            for (op, response) in callsObj { sink.calls[op] = Value(wire: response) }
        }

        if vector.kind == "handler" {
            guard let handlerName = vector.field("handler")?.asString else { Issue.record("\(vector): missing handler"); return }
            let args = (vector.field("args")?.asArray ?? []).map { Value(wire: $0) }
            await interpreter.run(handler: handlerName, args: args, scope: scope, effects: sink)
        } else {
            guard let nodeId = vector.field("node")?.asString, let eventName = vector.field("event")?.asString else {
                Issue.record("\(vector): missing node/event"); return
            }
            let payload = Value(wire: vector.field("payload") ?? .object([:]))
            let repeatIndex = vector.field("repeatIndex")?.asNumber.map(Int.init)
            await interpreter.runEvent(eventName, root: document.root, nodeId: nodeId, payload: payload, repeatIndex: repeatIndex, scope: scope, effects: sink)
        }

        #expect(sink.errors.isEmpty, "\(vector): unexpected interpreter errors \(sink.errors)")

        guard let expectObj = vector.field("expect")?.asObject else { Issue.record("\(vector): missing expect"); return }
        if let expectedState = expectObj["state"]?.asObject {
            for (key, expectedWire) in expectedState {
                let expected = Value(wire: expectedWire)
                let actual = scope.state(key)
                #expect(approximatelyEqual(actual, expected, tolerance: 1e-9), "\(vector): state.\(key) got \(actual), expected \(expected)")
            }
        }
        if let expectedEffects = expectObj["effects"]?.asArray {
            let expected = expectedEffects.map { Value(wire: $0) }
            #expect(sink.effects == expected, "\(vector): effects got \(sink.effects), expected \(expected)")
        }
    }

    // MARK: timeline

    private func runTimelineVector(_ vector: ConformanceCase) throws {
        guard let timelineWire = vector.field("timeline") else { Issue.record("\(vector): missing timeline"); return }
        let timeline = try Timeline(name: vector.name, wire: timelineWire)
        guard let samples = vector.field("samples")?.asArray else { Issue.record("\(vector): missing samples"); return }
        for sample in samples {
            guard let sObj = sample.asObject, let t = sObj["t"]?.asNumber, let index = sObj["index"]?.asNumber,
                  let expectObj = sObj["expect"]?.asObject else { continue }
            let result = TimelineSampler.sample(timeline, at: t, index: Int(index))
            for (key, expectedWire) in expectObj {
                guard let expected = expectedWire.asNumber else { continue }
                let actual = result[key] ?? .nan
                #expect(abs(actual - expected) <= 1e-6, "\(vector): \(key) at t=\(t) index=\(index) got \(actual), expected \(expected)")
            }
        }
    }

    // MARK: shared scope setup (harness rule 1)

    private func makeScope(_ vector: ConformanceCase, document: Document, interpreter: Interpreter) throws -> MapScope {
        let params = (vector.field("params")?.asObject ?? [:]).mapValues { Value(wire: $0) }
        let data = (vector.field("data")?.asObject ?? [:]).mapValues { Value(wire: $0) }
        let env = (vector.field("env")?.asObject ?? [:]).mapValues { Value(wire: $0) }
        let stateOverrides = (vector.field("state")?.asObject ?? [:]).mapValues { Value(wire: $0) }
        return MapScope(document: document, interpreter: interpreter, params: params, data: data, env: env, stateOverrides: stateOverrides)
    }
}
